window.products.push({"id":280115,"name":"Maverick Digital Refrigerator/Freezer Thermometer","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71N0lxkRPPL._AC_SL1500_.jpg","description":"Help keep your food at its optimal freshness by monitoring your refrigerator and freezer with this Maverick digital thermometer (model RF-02). In addition to instantly knowing the current temperature, the thermometer also provides the weekly average temperature for both the fridge and freezer. It updates instant readings every 5 seconds and average readings every 5 minutes. Other features include a Thermistor extension wire for the freezer compartment, self adhesive mounting bracket, low battery detector, and readings in either Fahrenheit or Celsius. It's powered by two AAA batteries (included).","images":["https://m.media-amazon.com/images/I/71N0lxkRPPL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Maverick","source_asin":"B0000AQL26","category_path":"Home & Kitchen"},"sku":"BM-280115","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0000AQL26","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0000AQL26","price_pending":true,"merchant_ready":false});
